-- Data migration: YDS Kelime topics (core verbs/nouns/adjectives/adverbs + past-exam word list) and the
-- Dil bilgisi sequence. Generated by scripts/build-yds-curriculum-migration.mts from lib/yds-curriculum.ts.
-- Idempotent and YDS-only: topics upsert on (examTypeId, slug); lessons update by (topic, position) or are
-- inserted when missing; nothing is deleted. No-op when the YDS exam type does not exist.

INSERT INTO "exam_topics" ("id", "examTypeId", "name", "slug", "questionCount", "difficulty", "displayOrder", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, id, $ydsc$Kelime – Sık Çıkan Fiiller$ydsc$, $ydsc$kelime-sik-cikan-fiiller$ydsc$, NULL, $ydsc$Orta$ydsc$, 1, now(), now() FROM "exam_types" WHERE "code" = 'YDS'
ON CONFLICT ("examTypeId", "slug") DO UPDATE SET "name" = EXCLUDED."name", "questionCount" = EXCLUDED."questionCount", "difficulty" = EXCLUDED."difficulty", "displayOrder" = EXCLUDED."displayOrder", "updatedAt" = now();

UPDATE "topic_lessons" SET "title" = $ydsc$Kelime – Sık Çıkan Fiiller – Konuya Giriş$ydsc$, "durationMinutes" = 8, "contentBody" = $ydsc$YDS'nin kelime bölümündeki soruların en büyük payı fiillere aittir ve bu fiillerin çoğu akademik metinlerden gelir: 'alleviate, undermine, exacerbate, facilitate, hinder, sustain' gibi. Bu liste, Netfener'in YDS ve akademik okuma metinlerinde en sık karşılaştığı fiillerden derlenmiştir; her fiilin Türkçe anlamı ve özgün bir örnek cümlesi vardır.

Sınavda nasıl karşınıza çıkar?
Kelime sorusunda boşluğa uyan fiili bulmak için cümledeki nesneye ve bağlama bakın: 'to ---- the effects of the disease' boşluğu olumsuz bir şeyi azaltan bir fiil ('alleviate, mitigate') ister. Fiillerin aldığı edatlar da ipucudur: 'attribute A to B', 'comply with', 'deprive sb of sth', 'adhere to'.

Nasıl çalışmalısınız?
Her gün bir bölümden 20–30 fiil seçin; Türkçe anlamı kapatıp örnek cümleden anlamı tahmin edin. Olumlu/olumsuz anlam yönünü (artırmak mı, azaltmak mı; desteklemek mi, engellemek mi) not edin; YDS'de seçenekler çoğunlukla bu yön üzerinden ayrışır.

Sonuç olarak, fiilleri tek tek ezberlemek yerine eş ve zıt anlamlı gruplar hâlinde (hinder – impede – hamper / facilitate – foster – promote) tekrar etmek hem kelime sorularında hem de paragraf ve çeviri sorularında hız kazandırır.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$kelime-sik-cikan-fiiller$ydsc$) AND "position" = 0;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Kelime – Sık Çıkan Fiiller – Konuya Giriş$ydsc$, 0, 8, $ydsc$YDS'nin kelime bölümündeki soruların en büyük payı fiillere aittir ve bu fiillerin çoğu akademik metinlerden gelir: 'alleviate, undermine, exacerbate, facilitate, hinder, sustain' gibi. Bu liste, Netfener'in YDS ve akademik okuma metinlerinde en sık karşılaştığı fiillerden derlenmiştir; her fiilin Türkçe anlamı ve özgün bir örnek cümlesi vardır.

Sınavda nasıl karşınıza çıkar?
Kelime sorusunda boşluğa uyan fiili bulmak için cümledeki nesneye ve bağlama bakın: 'to ---- the effects of the disease' boşluğu olumsuz bir şeyi azaltan bir fiil ('alleviate, mitigate') ister. Fiillerin aldığı edatlar da ipucudur: 'attribute A to B', 'comply with', 'deprive sb of sth', 'adhere to'.

Nasıl çalışmalısınız?
Her gün bir bölümden 20–30 fiil seçin; Türkçe anlamı kapatıp örnek cümleden anlamı tahmin edin. Olumlu/olumsuz anlam yönünü (artırmak mı, azaltmak mı; desteklemek mi, engellemek mi) not edin; YDS'de seçenekler çoğunlukla bu yön üzerinden ayrışır.

Sonuç olarak, fiilleri tek tek ezberlemek yerine eş ve zıt anlamlı gruplar hâlinde (hinder – impede – hamper / facilitate – foster – promote) tekrar etmek hem kelime sorularında hem de paragraf ve çeviri sorularında hız kazandırır.$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$kelime-sik-cikan-fiiller$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 0);

UPDATE "topic_lessons" SET "title" = $ydsc$Kelime – Sık Çıkan Fiiller – Kelime Sözlüğü (1/3): A–D$ydsc$, "durationMinutes" = 20, "contentBody" = $ydsc$abandon (fiil) – terk etmek, bırakmak
Örnek: "They abandoned the car on the road." (Arabayı yolda terk ettiler.)

accelerate (fiil) – hızlanmak, hızlandırmak
Örnek: "Climate change is accelerating." (İklim değişikliği hızlanıyor.)

accommodate (fiil) – barındırmak; uyum sağlamak
Örnek: "The hotel can accommodate 300 guests." (Otel 300 misafir barındırabilir.)

accumulate (fiil) – biriktirmek, birikmek
Örnek: "Dust accumulates on the shelves." (Raflarda toz birikir.)

acknowledge (fiil) – kabul etmek, teslim etmek
Örnek: "He acknowledged that he was wrong." (Yanıldığını kabul etti.)

acquire (fiil) – edinmek, kazanmak
Örnek: "Children acquire language naturally." (Çocuklar dili doğal olarak edinir.)

adhere (fiil) – yapışmak; bağlı kalmak
Örnek: "All staff must adhere to the rules." (Tüm çalışanlar kurallara bağlı kalmalıdır.)

advocate (fiil) – savunmak, desteklemek
Örnek: "Many experts advocate stricter emission limits." (Pek çok uzman daha sıkı emisyon sınırlarını savunuyor.)

affect (fiil) – etkilemek
Örnek: "The weather affects my mood." (Hava ruh hâlimi etkiliyor.)

alleviate (fiil) – hafifletmek
Örnek: "The drug alleviates pain." (İlaç ağrıyı hafifletir.)

allocate (fiil) – tahsis etmek, ayırmak
Örnek: "Funds were allocated to schools." (Okullara fon ayrıldı.)

alter (fiil) – değiştirmek (biraz)
Örnek: "The tailor altered my suit." (Terzi takımımda değişiklik yaptı.)

anticipate (fiil) – öngörmek, beklemek
Örnek: "We anticipate heavy traffic today." (Bugün yoğun trafik bekliyoruz.)

ascertain (fiil) – tespit etmek, kesinleştirmek
Örnek: "We need to ascertain the facts." (Gerçekleri tespit etmemiz gerek.)

assert (fiil) – ileri sürmek, iddia etmek
Örnek: "He asserted that he was innocent." (Masum olduğunu ileri sürdü.)

assess (fiil) – değerlendirmek, ölçmek
Örnek: "The test assesses reading skills." (Test okuma becerilerini ölçer.)

attain (fiil) – elde etmek, ulaşmak
Örnek: "She attained her goal after years." (Yıllar sonra hedefine ulaştı.)

attribute (fiil) – (bir nedene) bağlamak, atfetmek (attribute A to B)
Örnek: "Researchers attribute the decline in bee populations to pesticide use." (Araştırmacılar arı popülasyonundaki düşüşü pestisit kullanımına bağlıyor.)

augment (fiil) – artırmak, çoğaltmak
Örnek: "The hospital recruited staff to augment its capacity." (Hastane kapasitesini artırmak için personel aldı.)

bolster (fiil) – desteklemek, güçlendirmek
Örnek: "The win bolstered the team's confidence." (Galibiyet takımın özgüvenini güçlendirdi.)

cease (fiil) – sona ermek, durmak
Örnek: "The noise ceased at midnight." (Gürültü gece yarısı sona erdi.)

coincide (fiil) – aynı zamana denk gelmek; örtüşmek (coincide with)
Örnek: "The protest coincided with the president's visit to the city." (Protesto, cumhurbaşkanının şehre ziyaretine denk geldi.)

compel (fiil) – zorlamak, mecbur bırakmak
Örnek: "Financial difficulties compelled them to sell the house." (Maddi güçlükler onları evi satmaya mecbur bıraktı.)

compensate (fiil) – tazmin etmek, telafi etmek
Örnek: "The airline compensated the passengers." (Havayolu yolcuların zararını tazmin etti.)

comply (fiil) – uymak
Örnek: "All drivers must comply with the law." (Tüm sürücüler yasaya uymak zorundadır.)

comprise (fiil) – içermek, oluşmak
Örnek: "The team comprises ten members." (Takım on üyeden oluşur.)

conceal (fiil) – gizlemek
Örnek: "He concealed the truth from them." (Gerçeği onlardan gizledi.)

concede (fiil) – kabul etmek (istemeyerek)
Örnek: "He conceded that she had a point." (Onun haklı olduğunu kabul etti.)

conduct (fiil) – yürütmek, yapmak (araştırma)
Örnek: "They conducted a survey of 500 people." (500 kişiyle bir anket yaptılar.)

confine (fiil) – sınırlamak; kapatmak
Örnek: "The analysis is confined to data from urban areas." (Analiz kentsel alanlardan gelen verilerle sınırlıdır.)

confront (fiil) – yüzleşmek, karşı koymak
Örnek: "She confronted her fears." (Korkularıyla yüzleşti.)

constitute (fiil) – oluşturmak, teşkil etmek
Örnek: "Women constitute half the workforce." (Kadınlar iş gücünün yarısını oluşturuyor.)

contradict (fiil) – çelişmek; yalanlamak
Örnek: "The results contradict the theory." (Sonuçlar kuramla çelişiyor.)

convey (fiil) – aktarmak, iletmek
Örnek: "Pictures can convey emotions better than words." (Resimler duyguları kelimelerden daha iyi aktarabilir.)

curb (fiil) – dizginlemek, sınırlamak
Örnek: "The government introduced new taxes to curb inflation." (Hükümet enflasyonu dizginlemek için yeni vergiler getirdi.)

deem (fiil) – saymak, addetmek, kabul etmek
Örnek: "The bridge was deemed unsafe after the earthquake." (Köprü depremden sonra güvensiz kabul edildi.)

defer (fiil) – ertelemek; (defer to) birinin görüşüne uymak
Örnek: "The committee deferred its decision until more data was available." (Komite, daha fazla veri elde edilene kadar kararını erteledi.)

deplete (fiil) – tüketmek, azaltmak
Örnek: "Intensive farming can deplete nutrients in the soil." (Yoğun tarım topraktaki besinleri tüketebilir.)

deprive (fiil) – mahrum bırakmak (deprive sb of sth)
Örnek: "Long working hours deprive many employees of sleep." (Uzun çalışma saatleri birçok çalışanı uykudan mahrum bırakıyor.)

derive (fiil) – (from) türemek, elde etmek
Örnek: "Many English words derive from Latin." (Pek çok İngilizce kelime Latinceden türemiştir.)

deteriorate (fiil) – kötüleşmek
Örnek: "His health deteriorated quickly." (Sağlığı hızla kötüleşti.)

devise (fiil) – tasarlamak, geliştirmek (plan, yöntem)
Örnek: "Engineers devised a cheaper way to purify drinking water." (Mühendisler içme suyunu arıtmanın daha ucuz bir yolunu geliştirdi.)

diminish (fiil) – azalmak
Örnek: "Her interest in the project diminished." (Projeye ilgisi azaldı.)

discern (fiil) – sezmek, ayırt etmek
Örnek: "It's hard to discern his true feelings." (Gerçek duygularını sezmek zor.)

disclose (fiil) – açıklamak, ifşa etmek
Örnek: "The firm disclosed its profits." (Firma kârını açıkladı.)

disrupt (fiil) – sarsmak, altüst etmek (sektörü)
Örnek: "Streaming disrupted the music industry." (Dijital yayın müzik sektörünü altüst etti.)

dissipate (fiil) – dağılmak, yok olmak; boşa harcamak
Örnek: "The fog dissipated as the sun rose." (Güneş yükseldikçe sis dağıldı.)

distort (fiil) – çarpıtmak, bozmak
Örnek: "The media distorted the facts." (Medya gerçekleri çarpıttı.)

diverge (fiil) – ayrılmak, farklılaşmak
Örnek: "The two paths diverge here." (İki yol burada ayrılıyor.)$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$kelime-sik-cikan-fiiller$ydsc$) AND "position" = 1;

