SELECT gen_random_uuid()::text, id, $ydsc$Kelime – Sık Çıkan İsimler$ydsc$, $ydsc$kelime-sik-cikan-isimler$ydsc$, NULL, $ydsc$Orta$ydsc$, 2, now(), now() FROM "exam_types" WHERE "code" = 'YDS'
ON CONFLICT ("examTypeId", "slug") DO UPDATE SET "name" = EXCLUDED."name", "questionCount" = EXCLUDED."questionCount", "difficulty" = EXCLUDED."difficulty", "displayOrder" = EXCLUDED."displayOrder", "updatedAt" = now();

UPDATE "topic_lessons" SET "title" = $ydsc$Kelime – Sık Çıkan İsimler – Konuya Giriş$ydsc$, "durationMinutes" = 8, "contentBody" = $ydsc$Akademik metinler soyut isimlerle doludur: 'consequence, implication, prevalence, threshold, consensus, drawback'. YDS'de bu isimler hem kelime sorusu olarak hem de paragraf ve çeviri sorularındaki kilit kavramlar olarak karşınıza çıkar. Bu liste, Netfener'in YDS düzeyindeki metinlerde en sık gördüğü isimlerden oluşur.

Sınavda nasıl karşınıza çıkar?
İsim sorularında boşluk genellikle bir belirleyiciden (the, a, its) ya da sıfattan sonra gelir. Doğru ismi bulmak için çevresindeki edatlara bakın: 'a decline IN', 'an obstacle TO', 'the prevalence OF', 'susceptibility TO'. İsimlerin sabit edatları çoğu zaman tek doğru seçeneği belirler.

Nasıl çalışmalısınız?
Her ismi kendi fiil ve sıfat ailesiyle birlikte öğrenin: 'emerge – emergence – emergent', 'vulnerable – vulnerability'. Böylece bir kelimeyi öğrenirken üç dört kelime kazanırsınız ve 'sözcük türü' sorularında da avantaj sağlarsınız.

Sonuç olarak, soyut isimler paragraf sorularındaki ana fikir cümlelerinin anahtarıdır; bu listeyi düzenli tekrar etmek hem kelime sorularında hem de okuduğunu anlamada doğrudan puan getirir.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$kelime-sik-cikan-isimler$ydsc$) AND "position" = 0;

