INSERT INTO "exam_topics" ("id", "examTypeId", "name", "slug", "questionCount", "difficulty", "displayOrder", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, id, $ydsc$Kelime – Sık Çıkan Zarflar$ydsc$, $ydsc$kelime-sik-cikan-zarflar$ydsc$, NULL, $ydsc$Orta$ydsc$, 4, now(), now() FROM "exam_types" WHERE "code" = 'YDS'
ON CONFLICT ("examTypeId", "slug") DO UPDATE SET "name" = EXCLUDED."name", "questionCount" = EXCLUDED."questionCount", "difficulty" = EXCLUDED."difficulty", "displayOrder" = EXCLUDED."displayOrder", "updatedAt" = now();

UPDATE "topic_lessons" SET "title" = $ydsc$Kelime – Sık Çıkan Zarflar – Konuya Giriş$ydsc$, "durationMinutes" = 8, "contentBody" = $ydsc$Zarflar, YDS kelime sorularının düzenli olarak sorduğu ama adayların en az çalıştığı gruptur: 'merely, readily, invariably, barely, presumably, inadvertently, ultimately'. Bu liste, YDS düzeyindeki metinlerde sık geçen zarfları ve cümleleri birbirine bağlayan 'consequently, nevertheless, likewise, conversely' gibi geçiş ifadelerini özgün örneklerle sunar.

Sınavda nasıl karşınıza çıkar?
Zarf sorularında cümlenin genel anlamına ve vurgusuna bakın: 'barely / hardly / scarcely' neredeyse olumsuz bir anlam verir; 'virtually' neredeyse tamamen, 'merely / solely' yalnızca, 'arguably' tartışmaya açık olsa da anlamı taşır. Geçiş zarfları (however, consequently, likewise) ise iki cümle arasındaki mantık ilişkisini kurar ve cloze testte de sık sorulur.

Nasıl çalışmalısınız?
Zarfları anlam gruplarına ayırarak tekrar edin: derece (considerably, markedly, drastically), sıklık (invariably, seldom), tutum (apparently, presumably, allegedly), bağlantı (consequently, nevertheless, likewise). Her grubun içindeki ince farkları örnek cümlelerle pekiştirin.

Sonuç olarak, zarfları bilmek yalnızca kelime sorularında değil, paragraf sorularında yazarın kesinlik derecesini (kesin mi söylüyor, tahmin mi ediyor) anlamada da belirleyicidir.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$kelime-sik-cikan-zarflar$ydsc$) AND "position" = 0;

