SELECT gen_random_uuid()::text, id, $ydsc$Kelime – KPDS, ÜDS ve YDS'de Çıkmış Kelimeler$ydsc$, $ydsc$kelime-cikmis-kelimeler$ydsc$, NULL, $ydsc$Orta$ydsc$, 5, now(), now() FROM "exam_types" WHERE "code" = 'YDS'
ON CONFLICT ("examTypeId", "slug") DO UPDATE SET "name" = EXCLUDED."name", "questionCount" = EXCLUDED."questionCount", "difficulty" = EXCLUDED."difficulty", "displayOrder" = EXCLUDED."displayOrder", "updatedAt" = now();

UPDATE "topic_lessons" SET "title" = $ydsc$Kelime – KPDS, ÜDS ve YDS'de Çıkmış Kelimeler – Konuya Giriş$ydsc$, "durationMinutes" = 8, "contentBody" = $ydsc$Bu bölüm, geçmiş KPDS, ÜDS ve YDS sınavlarında çıkmış 1124 kelimeyi alfabetik sırayla bir araya getirir. Kelimelerin bir kısmı temel düzeydedir, bir kısmı ise akademik metinlerde sık geçen ileri düzey kelimelerdir; liste, sınavın kelime düzeyini tanımanız ve eksiklerinizi görmeniz için hazırlandı. Türkçe anlamlar ve örnek cümleler Netfener tarafından yazılmıştır.

Sınavda nasıl karşınıza çıkar?
Bu kelimeler kelime sorularında doğrudan seçenek olarak; cümle tamamlama, çeviri ve paragraf sorularında ise metnin içinde karşınıza çıkar. Çok anlamlı kelimelerde (ör. 'found': kurmak / bulmak fiilinin geçmişi, 'resume': yeniden başlamak / özgeçmiş) her iki anlamı da öğrenmek önemlidir; YDS bu tür kelimelerin daha az bilinen anlamını sormayı sever.

Nasıl çalışmalısınız?
Her gün yaklaşık 40 kelimelik bir bölüm seçin ve sesli okuyun. Türkçe anlamı kapatıp hatırlamaya çalışın; hatırlayamadığınız kelimeleri bir deftere ya da Kelime Motoru'na ekleyin. Bu tempoyla liste 4–6 haftada bitirilir; ikinci turda yalnızca işaretlediğiniz kelimelere dönün.

Sonuç olarak, çıkmış kelimeler listesi sınavın kelime havuzunu tanımanın en kısa yoludur. Bu listeyi 'Sık Çıkan Fiiller, İsimler, Sıfatlar ve Zarflar' bölümleriyle birlikte çalışmak, hem temel hem de akademik kelime ihtiyacınızı birlikte karşılar.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$kelime-cikmis-kelimeler$ydsc$) AND "position" = 0;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Kelime – KPDS, ÜDS ve YDS'de Çıkmış Kelimeler – Konuya Giriş$ydsc$, 0, 8, $ydsc$Bu bölüm, geçmiş KPDS, ÜDS ve YDS sınavlarında çıkmış 1124 kelimeyi alfabetik sırayla bir araya getirir. Kelimelerin bir kısmı temel düzeydedir, bir kısmı ise akademik metinlerde sık geçen ileri düzey kelimelerdir; liste, sınavın kelime düzeyini tanımanız ve eksiklerinizi görmeniz için hazırlandı. Türkçe anlamlar ve örnek cümleler Netfener tarafından yazılmıştır.

Sınavda nasıl karşınıza çıkar?
Bu kelimeler kelime sorularında doğrudan seçenek olarak; cümle tamamlama, çeviri ve paragraf sorularında ise metnin içinde karşınıza çıkar. Çok anlamlı kelimelerde (ör. 'found': kurmak / bulmak fiilinin geçmişi, 'resume': yeniden başlamak / özgeçmiş) her iki anlamı da öğrenmek önemlidir; YDS bu tür kelimelerin daha az bilinen anlamını sormayı sever.

Nasıl çalışmalısınız?
Her gün yaklaşık 40 kelimelik bir bölüm seçin ve sesli okuyun. Türkçe anlamı kapatıp hatırlamaya çalışın; hatırlayamadığınız kelimeleri bir deftere ya da Kelime Motoru'na ekleyin. Bu tempoyla liste 4–6 haftada bitirilir; ikinci turda yalnızca işaretlediğiniz kelimelere dönün.

Sonuç olarak, çıkmış kelimeler listesi sınavın kelime havuzunu tanımanın en kısa yoludur. Bu listeyi 'Sık Çıkan Fiiller, İsimler, Sıfatlar ve Zarflar' bölümleriyle birlikte çalışmak, hem temel hem de akademik kelime ihtiyacınızı birlikte karşılar.$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$kelime-cikmis-kelimeler$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 0);

UPDATE "topic_lessons" SET "title" = $ydsc$Kelime – KPDS, ÜDS ve YDS'de Çıkmış Kelimeler – Kelime Sözlüğü (1/9): A–B$ydsc$, "durationMinutes" = 18, "contentBody" = $ydsc$abolish (fiil) – kaldırmak, ilga etmek
Örnek: "The country abolished the death penalty in 2004." (Ülke idam cezasını 2004'te kaldırdı.)

abolition (isim) – kaldırılma, yürürlükten kaldırma (köleliğin kaldırılması gibi)

absorb (fiil) – emmek, özümsemek
Örnek: "Sponges absorb water quickly." (Süngerler suyu hızla emer.)

abuse (isim) – kötüye kullanma, istismar; (v) kötüye kullanmak

academic (sıfat) – akademik
Örnek: "This is an academic book." (Bu akademik bir kitap.)

accelerator (isim) – gaz pedalı; hızlandırıcı

accent (isim) – aksan
Örnek: "She speaks English with a Scottish accent." (İngilizceyi İskoç aksanıyla konuşuyor.)

access (isim) – erişim
Örnek: "Students have free access to the library." (Öğrencilerin kütüphaneye ücretsiz erişimi var.)

accessible (sıfat) – ulaşılabilir, erişilebilir; anlaşılır

accounting (isim) – muhasebe

accumulate (fiil) – biriktirmek, birikmek
Örnek: "Dust accumulates on the shelves." (Raflarda toz birikir.)

accused (isim) – sanık; (adj) suçlanan

accustom (fiil) – alıştırmak (accustom oneself to: -e alışmak)

accustomed (sıfat) – alışkın, alışık (be accustomed to + V-ing)

achieve (fiil) – başarmak
Örnek: "You can achieve your goals." (Hedeflerine ulaşabilirsin.)

achievement (isim) – başarı, kazanım
Örnek: "Graduating was a great achievement." (Mezun olmak büyük bir başarıydı.)

acid (isim) – asit
Örnek: "Lemon juice contains acid." (Limon suyu asit içerir.)

acknowledge (fiil) – kabul etmek, teslim etmek
Örnek: "He acknowledged that he was wrong." (Yanıldığını kabul etti.)

acquire (fiil) – edinmek, kazanmak
Örnek: "Children acquire language naturally." (Çocuklar dili doğal olarak edinir.)

acquisition (isim) – satın alma (şirket)
Örnek: "The acquisition cost $2 billion." (Satın alma 2 milyar dolara mal oldu.)

addict (isim) – bağımlı, tiryaki

admiral (isim) – amiral

admission (isim) – giriş, kabul; itiraf

adopt (fiil) – evlat edinmek
Örnek: "They adopted a baby girl." (Bir kız bebek evlat edindiler.)

adverse (sıfat) – olumsuz, elverişsiz
Örnek: "The medication may cause adverse effects." (İlaç olumsuz etkilere yol açabilir.)

airport (isim) – havalimanı
Örnek: "We go to the airport by taxi." (Havalimanına taksiyle gideriz.)

album (isim) – albüm
Örnek: "Her new album comes out in May." (Yeni albümü mayısta çıkıyor.)

alcohol (isim) – alkol
Örnek: "Alcohol is banned on the premises." (Alkol bu alanda yasaktır.)

allocate (fiil) – tahsis etmek, ayırmak
Örnek: "Funds were allocated to schools." (Okullara fon ayrıldı.)

allocations (isim) – tahsisler, ayrılan paylar

allowance (isim) – ödenek, harçlık; tolerans
Örnek: "He gets a monthly allowance from his parents." (Anne babasından aylık harçlık alıyor.)

ally (isim) – müttefik
Örnek: "The two countries are close allies." (İki ülke yakın müttefik.)

alphabet (isim) – alfabe

alter (fiil) – değiştirmek (biraz)
Örnek: "The tailor altered my suit." (Terzi takımımda değişiklik yaptı.)

alternative (isim) – alternatif, seçenek
Örnek: "Is there a cheaper alternative?" (Daha ucuz bir alternatif var mı?)

amateur (sıfat) – amatör
Örnek: "He plays in an amateur football team." (Amatör bir futbol takımında oynuyor.)

ambulance (isim) – ambulans
Örnek: "Call an ambulance!" (Ambulans çağırın!)

amend (fiil) – değiştirmek, düzeltmek (metin, yasa)
Örnek: "Parliament amended the law." (Meclis yasayı değiştirdi.)

ample (sıfat) – bol, yeterinden fazla
Örnek: "There's ample time to finish." (Bitirmek için bolca zaman var.)

anchor (isim) – çapa; (v) demir atmak, sabitlemek

angel (isim) – melek

anger (isim) – öfke
Örnek: "He couldn't hide his anger." (Öfkesini saklayamadı.)

angle (isim) – açı; bakış açısı

anticipate (fiil) – öngörmek, beklemek
Örnek: "We anticipate heavy traffic today." (Bugün yoğun trafik bekliyoruz.)

antique (isim) – antika; (adj) antika, eski

anxiously (zarf) – endişeyle, kaygıyla; merakla

apartment (isim) – apartman dairesi
Örnek: "They rent a small apartment downtown." (Şehir merkezinde küçük bir daire kiralıyorlar.)

apparently (zarf) – görünüşe göre, anlaşılan
Örnek: "Apparently, the shop is closing down." (Görünüşe göre dükkân kapanıyor.)

articles of association (isim) – şirket ana sözleşmesi

aspect (isim) – yön, açı, boyut
Örnek: "We discussed every aspect of the plan." (Planın her yönünü tartıştık.)

asset (isim) – varlık
Örnek: "Property is their main asset." (Emlak onların ana varlığı.)

association (isim) – dernek; ilişkilendirme
Örnek: "She joined a local women's association." (Yerel bir kadın derneğine katıldı.)

assurance (isim) – güvence, teminat; sigorta

assure (fiil) – temin etmek, güvence vermek
Örnek: "I assure you everything is fine." (Sizi temin ederim ki her şey yolunda.)

assured (sıfat) – kesin, garantili; kendinden emin

attachment (isim) – bağlanma
Örnek: "Early attachment affects adult relationships." (Erken bağlanma yetişkin ilişkilerini etkiler.)

attendant (isim) – görevli, refakatçi; (adj) beraberinde gelen

auction (isim) – müzayede
Örnek: "The painting sold at auction for millions." (Tablo müzayedede milyonlara satıldı.)

audience (isim) – seyirci
Örnek: "The audience loved the show." (Seyirciler gösteriye bayıldı.)

augment (fiil) – artırmak, çoğaltmak
Örnek: "The hospital recruited staff to augment its capacity." (Hastane kapasitesini artırmak için personel aldı.)

augmentation (isim) – artırma, büyütme, artış

author (isim) – yazar
Örnek: "Who is the author of this book?" (Bu kitabın yazarı kim?)

authority (isim) – yetkili makam, otorite
Örnek: "The local authority built a new school." (Yerel yönetim yeni bir okul yaptı.)

award (isim) – ödül (resmi)
Örnek: "The film won three awards." (Film üç ödül kazandı.)

awkward (sıfat) – garip, tuhaf; rahatsız edici
Örnek: "There was an awkward silence." (Garip bir sessizlik oldu.)

babysitter (isim) – çocuk bakıcısı

bachelor (isim) – bekâr erkek; lisans mezunu (Bachelor's degree)

backbone (isim) – omurga; temel destek
Örnek: "Farming is the backbone of the local economy." (Tarım, yerel ekonominin omurgasıdır.)

bale (isim) – balya, denk

banal (sıfat) – sıradan, basmakalıp

bandage (isim) – bandaj
Örnek: "The nurse put a bandage on my arm." (Hemşire koluma bandaj sardı.)

baneful (sıfat) – zararlı, öldürücü

banish (fiil) – sürgüne göndermek; kafasından atmak

barbarous (sıfat) – barbarca, vahşi

barber (isim) – berber

basin (isim) – lavabo, leğen; havza

bastardize (fiil) – bozmak, niteliğini düşürmek

battery (isim) – pil, batarya
Örnek: "My phone battery is low." (Telefonumun şarjı az.)

bawl (fiil) – bağırmak, avazı çıktığı kadar ağlamak

beforehand (zarf) – önceden, peşinen

bias (isim) – önyargı, taraflılık
Örnek: "The article shows a clear bias." (Makale açık bir taraflılık gösteriyor.)

birthday (isim) – doğum günü
Örnek: "Happy birthday!" (Doğum günün kutlu olsun!)

bladder (isim) – mesane, idrar torbası
Örnek: "He had an infection of the bladder." (Mesane enfeksiyonu geçirdi.)

blade (isim) – bıçak ağzı, jilet; (ot) yaprak

