WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-temel-cumle-yapisi$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 1);

UPDATE "topic_lessons" SET "title" = $ydsc$Temel Cümle Yapısı ve Sözcük Türleri – Örnek Sorular ve Çözümler$ydsc$, "durationMinutes" = 10, "contentBody" = $ydsc$Örnek 1: Örnek soru: "The rapid ---- of renewable energy has reduced the country's dependence on imported fuel."
(A) expand (B) expansive (C) expansion (D) expansively
Doğru cevap (C) 'expansion' — 'The rapid ----' yapısında boşluk bir belirleyici ve sıfattan sonra geldiği için isim ister; 'expansion' (genişleme) tek isim seçenektir. 'expand' fiil, 'expansive' sıfat, 'expansively' zarftır.

Örnek 2: Örnek soru: "The findings of the survey, which was carried out in twelve cities, ---- that most people support the reform."
(A) suggests (B) suggest (C) suggesting (D) to suggest
Doğru cevap (B) 'suggest' — Ana özne 'The findings' çoğuldur; araya giren 'of the survey, which was...' fiilin çekimini değiştirmez. Cümlede çekimli ana fiil eksik olduğu için '-ing' ve 'to' seçenekleri de elenir.

Örnek 3: Örnek soru: "---- is widely believed that regular exercise improves memory."
(A) There (B) What (C) It (D) This
Doğru cevap (C) 'It' — Asıl özne 'that regular exercise improves memory' cümleciğidir ve sona atılmıştır; başa boş özne 'It' gelir. 'There' bir varlık bildirir ve 'is believed that' ile kullanılmaz.

Örnek 4: Örnek soru: "Unemployment ---- steadily over the last decade, despite several government programmes."
(A) has risen (B) has raised (C) has been risen (D) raised
Doğru cevap (A) 'has risen' — 'rise' (yükselmek) geçişsizdir, nesne almaz ve edilgen olamaz; 'raise' (yükseltmek) ise nesne ister. 'over the last decade' Present Perfect gerektirir, bu yüzden doğru cevap 'has risen'dır.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-temel-cumle-yapisi$ydsc$) AND "position" = 2;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Temel Cümle Yapısı ve Sözcük Türleri – Örnek Sorular ve Çözümler$ydsc$, 2, 10, $ydsc$Örnek 1: Örnek soru: "The rapid ---- of renewable energy has reduced the country's dependence on imported fuel."
(A) expand (B) expansive (C) expansion (D) expansively
Doğru cevap (C) 'expansion' — 'The rapid ----' yapısında boşluk bir belirleyici ve sıfattan sonra geldiği için isim ister; 'expansion' (genişleme) tek isim seçenektir. 'expand' fiil, 'expansive' sıfat, 'expansively' zarftır.

Örnek 2: Örnek soru: "The findings of the survey, which was carried out in twelve cities, ---- that most people support the reform."
(A) suggests (B) suggest (C) suggesting (D) to suggest
Doğru cevap (B) 'suggest' — Ana özne 'The findings' çoğuldur; araya giren 'of the survey, which was...' fiilin çekimini değiştirmez. Cümlede çekimli ana fiil eksik olduğu için '-ing' ve 'to' seçenekleri de elenir.

Örnek 3: Örnek soru: "---- is widely believed that regular exercise improves memory."
(A) There (B) What (C) It (D) This
Doğru cevap (C) 'It' — Asıl özne 'that regular exercise improves memory' cümleciğidir ve sona atılmıştır; başa boş özne 'It' gelir. 'There' bir varlık bildirir ve 'is believed that' ile kullanılmaz.

Örnek 4: Örnek soru: "Unemployment ---- steadily over the last decade, despite several government programmes."
(A) has risen (B) has raised (C) has been risen (D) raised
Doğru cevap (A) 'has risen' — 'rise' (yükselmek) geçişsizdir, nesne almaz ve edilgen olamaz; 'raise' (yükseltmek) ise nesne ister. 'over the last decade' Present Perfect gerektirir, bu yüzden doğru cevap 'has risen'dır.$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-temel-cumle-yapisi$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 2);

