SELECT gen_random_uuid()::text, id, $ydsc$Passive Voice (Edilgen Yapı)$ydsc$, $ydsc$gramer-passive-voice$ydsc$, NULL, $ydsc$Orta$ydsc$, 9, now(), now() FROM "exam_types" WHERE "code" = 'YDS'
ON CONFLICT ("examTypeId", "slug") DO UPDATE SET "name" = EXCLUDED."name", "questionCount" = EXCLUDED."questionCount", "difficulty" = EXCLUDED."difficulty", "displayOrder" = EXCLUDED."displayOrder", "updatedAt" = now();

UPDATE "topic_lessons" SET "title" = $ydsc$Passive Voice (Edilgen Yapı) – Konuya Giriş$ydsc$, "durationMinutes" = 8, "contentBody" = $ydsc$Akademik İngilizce, işi yapandan çok yapılan işe odaklandığı için edilgen yapıyı yoğun kullanır; YDS'nin bilimsel ve sosyal metinlerinde neredeyse her paragrafta bir edilgen cümle bulunur. Gramer sorularında edilgen yapı genellikle zaman bilgisiyle birlikte test edilir: doğru seçenek hem doğru zamanda hem de doğru çatıda (etken/edilgen) olmalıdır.

Edilgen yapının formülü
Edilgen = be (zamana göre çekimli) + V3. Zamanı 'be' taşır: is made, was made, has been made, had been made, will be made, is being made, must be made, must have been made. Fiilin kendisi her zaman V3'te kalır.

Etken mi, edilgen mi?
Özne eylemi kendisi mi yapıyor, yoksa eylemden mi etkileniyor? 'The results were analysed' (sonuçlar analiz edildi) edilgendir çünkü sonuçlar kendini analiz edemez. Boşluktan sonra bir nesne varsa (fiil bir şeyi doğrudan etkiliyorsa) genellikle etken; nesne yoksa ve 'by' öbeği varsa edilgen gerekir. Geçişsiz fiiller (occur, happen, emerge, rise, arrive, exist) asla edilgen yapılmaz.

Ettirgen (causative) ve rapor yapıları
'have/get something done' işi başkasına yaptırmayı anlatır: 'She had her car repaired.' Rapor yapıları da edilgendir: 'It is believed that...' ya da 'He is believed to have left the country.' Bu ikinci kalıpta 'to V1' aynı zamanı, 'to have V3' daha önceki bir zamanı gösterir.

Sonuç olarak, edilgen sorularında üç adım izleyin: (1) özne eylemi yapıyor mu, (2) fiil geçişli mi, (3) zaman ipucu hangi 'be' biçimini gerektiriyor? Bu üç kontrol, edilgen sorularındaki seçeneklerin neredeyse tamamını ayırt etmeye yeter.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-passive-voice$ydsc$) AND "position" = 0;

