SELECT gen_random_uuid()::text, id, $ydsc$Conjunctions (Bağlaçlar)$ydsc$, $ydsc$gramer-conjunctions$ydsc$, NULL, $ydsc$Orta$ydsc$, 10, now(), now() FROM "exam_types" WHERE "code" = 'YDS'
ON CONFLICT ("examTypeId", "slug") DO UPDATE SET "name" = EXCLUDED."name", "questionCount" = EXCLUDED."questionCount", "difficulty" = EXCLUDED."difficulty", "displayOrder" = EXCLUDED."displayOrder", "updatedAt" = now();

UPDATE "topic_lessons" SET "title" = $ydsc$Conjunctions (Bağlaçlar) – Konuya Giriş$ydsc$, "durationMinutes" = 8, "contentBody" = $ydsc$Bağlaç soruları YDS'nin en çok puan getiren gramer sorularıdır, çünkü hem gramer bölümünde hem cloze testte hem de cümle tamamlamada karşınıza çıkar. Bu sorularda iki şey birlikte ölçülür: bağlacın ANLAMI (zıtlık, neden, sonuç, amaç, koşul, ekleme) ve bağlacın YAPISI (arkasından tam cümle mi, isim mi, -ing mi geliyor).

Anlam ilişkisini bulmak
Boşluğun iki yanındaki fikirleri yan yana koyun ve aralarındaki ilişkiyi Türkçe olarak söyleyin: '...e rağmen' (although, despite), '...dığı için' (because, since, due to), '...sın diye' (so that, in order to), '...dığı sürece' (as long as, provided that), 'bu yüzden' (therefore, thus). Yanlış seçeneklerin çoğu yapısı doğru ama anlamı ters olan bağlaçlardır.

Bağlaç mı, edat mı, cümle zarfı mı?
Aynı anlamı farklı yapılar taşır: 'although + cümle', 'despite + isim/-ing', 'however, + cümle (noktalı virgül ya da nokta sonrasında)'. 'because + cümle' ama 'because of + isim'. Boşluktan sonra özne ve çekimli fiil varsa bağlaç, sadece bir isim öbeği varsa edat gerekir; cümle zarfları (however, therefore, moreover) iki cümleyi tek başına bağlayamaz.

Eşli bağlaçlar
'both ... and', 'either ... or', 'neither ... nor', 'not only ... but also', 'whether ... or' çiftleri birbirinden ayrılmaz. Seçeneklerden biri cümledeki eşini tamamlıyorsa çoğu zaman doğrudan cevaptır. 'Neither ... nor' ve 'either ... or' yapılarında fiil kendisine yakın olan özneye göre çekilir.

Sonuç olarak, bağlaç sorularında önce yapıyı (cümle mi, isim mi), sonra anlamı (zıtlık mı, neden mi, amaç mı) kontrol edin. Yapı kontrolü genellikle iki seçeneği, anlam kontrolü ise kalanların çoğunu eler.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-conjunctions$ydsc$) AND "position" = 0;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Conjunctions (Bağlaçlar) – Konuya Giriş$ydsc$, 0, 8, $ydsc$Bağlaç soruları YDS'nin en çok puan getiren gramer sorularıdır, çünkü hem gramer bölümünde hem cloze testte hem de cümle tamamlamada karşınıza çıkar. Bu sorularda iki şey birlikte ölçülür: bağlacın ANLAMI (zıtlık, neden, sonuç, amaç, koşul, ekleme) ve bağlacın YAPISI (arkasından tam cümle mi, isim mi, -ing mi geliyor).

Anlam ilişkisini bulmak
Boşluğun iki yanındaki fikirleri yan yana koyun ve aralarındaki ilişkiyi Türkçe olarak söyleyin: '...e rağmen' (although, despite), '...dığı için' (because, since, due to), '...sın diye' (so that, in order to), '...dığı sürece' (as long as, provided that), 'bu yüzden' (therefore, thus). Yanlış seçeneklerin çoğu yapısı doğru ama anlamı ters olan bağlaçlardır.

Bağlaç mı, edat mı, cümle zarfı mı?
Aynı anlamı farklı yapılar taşır: 'although + cümle', 'despite + isim/-ing', 'however, + cümle (noktalı virgül ya da nokta sonrasında)'. 'because + cümle' ama 'because of + isim'. Boşluktan sonra özne ve çekimli fiil varsa bağlaç, sadece bir isim öbeği varsa edat gerekir; cümle zarfları (however, therefore, moreover) iki cümleyi tek başına bağlayamaz.

Eşli bağlaçlar
'both ... and', 'either ... or', 'neither ... nor', 'not only ... but also', 'whether ... or' çiftleri birbirinden ayrılmaz. Seçeneklerden biri cümledeki eşini tamamlıyorsa çoğu zaman doğrudan cevaptır. 'Neither ... nor' ve 'either ... or' yapılarında fiil kendisine yakın olan özneye göre çekilir.

Sonuç olarak, bağlaç sorularında önce yapıyı (cümle mi, isim mi), sonra anlamı (zıtlık mı, neden mi, amaç mı) kontrol edin. Yapı kontrolü genellikle iki seçeneği, anlam kontrolü ise kalanların çoğunu eler.$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-conjunctions$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 0);

UPDATE "topic_lessons" SET "title" = $ydsc$Conjunctions (Bağlaçlar) – Kurallar Referansı$ydsc$, "durationMinutes" = 12, "contentBody" = $ydsc$although / even though / though + cümle – Zıtlık: -e rağmen, -dığı hâlde.
Örnek: "Although the plan was risky, the board approved it." (Plan riskli olmasına rağmen yönetim kurulu onu onayladı.)

despite / in spite of + isim / V-ing – Zıtlık; arkasından cümle gelemez ('despite the fact that' + cümle hariç).
Örnek: "Despite rising costs, the factory increased production." (Artan maliyetlere rağmen fabrika üretimi artırdı.)

however / nevertheless / nonetheless – Cümle zarfı: ancak, yine de. Noktalı virgül veya noktadan sonra, virgülle kullanılır.
Örnek: "The drug is effective; however, it has serious side effects." (İlaç etkilidir; ancak ciddi yan etkileri vardır.)

whereas / while – İki durum arasında karşılaştırmalı zıtlık.
Örnek: "Some species thrive in heat, whereas others cannot survive above 30°C." (Bazı türler sıcakta gelişirken diğerleri 30°C'nin üzerinde yaşayamaz.)

because / since / as + cümle – Neden: -dığı için.
Örnek: "Since the data was incomplete, the study was repeated." (Veriler eksik olduğu için çalışma tekrarlandı.)

because of / due to / owing to + isim – Neden; arkasından isim öbeği gelir.
Örnek: "The flight was cancelled due to heavy fog." (Uçuş yoğun sis nedeniyle iptal edildi.)

so that / in order that + cümle (modal) – Amaç: -sın diye; genellikle can/could/will/would ile.
Örnek: "Leave the door open so that the cat can come in." (Kedi girebilsin diye kapıyı açık bırak.)

in order to / so as to + V1 – Amaç; olumsuzu 'so as not to / in order not to'.
Örnek: "She studied every night in order to pass the exam." (Sınavı geçmek için her gece çalıştı.)

therefore / thus / consequently / hence – Sonuç: bu nedenle, dolayısıyla.
Örnek: "The roads were icy; consequently, many schools closed." (Yollar buzluydu; sonuç olarak birçok okul kapandı.)

so + sıfat/zarf + that / such (a) + sıfat + isim + that – O kadar ... ki; arkasından tam cümle gelir.
Örnek: "The lecture was so complex that few students followed it." (Ders o kadar karmaşıktı ki az öğrenci takip edebildi.)

not only ... but also / both ... and – Ekleme: sadece ... değil, aynı zamanda.
Örnek: "The policy not only cut costs but also improved quality." (Politika sadece maliyetleri düşürmedi, aynı zamanda kaliteyi de artırdı.)

neither ... nor / either ... or – Ne ... ne / ya ... ya; fiil yakındaki özneye uyar.
Örnek: "Neither the manager nor the employees were informed." (Ne müdür ne de çalışanlar bilgilendirildi.)

moreover / furthermore / in addition – Ekleme: üstelik, buna ek olarak (cümle zarfı).
Örnek: "The car is cheap to run; moreover, it is easy to park." (Arabanın kullanımı ucuz; üstelik park etmesi de kolay.)$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-conjunctions$ydsc$) AND "position" = 1;

