ON CONFLICT ("examTypeId", "slug") DO UPDATE SET "name" = EXCLUDED."name", "questionCount" = EXCLUDED."questionCount", "difficulty" = EXCLUDED."difficulty", "displayOrder" = EXCLUDED."displayOrder", "updatedAt" = now();

UPDATE "topic_lessons" SET "title" = $ydsc$Noun Clauses (İsim Cümlecikleri) – Konuya Giriş$ydsc$, "durationMinutes" = 8, "contentBody" = $ydsc$İsim cümlecikleri bir cümlede özne, nesne ya da tümleç görevi gören yan cümlelerdir: 'What she said surprised me', 'I don't know whether he will come', 'The problem is that we have no data'. YDS'de bu konu en çok 'that / what / whether / if / soru kelimesi' seçimiyle ve dolaylı soru cümlesindeki söz dizimiyle test edilir.

that mi, what mi?
'that' anlam taşımaz; sadece bir cümleyi bağlar ve arkasından TAM bir cümle gelir: 'He said that the results were wrong.' 'what' ise 'şey/ne' anlamını kendi içinde taşır ve arkasından EKSİK bir cümle gelir (nesnesi ya da öznesi eksik): 'What surprised me was his answer.' Boşluktan sonraki cümlede bir öğe eksikse 'what', tamsa 'that' gerekir.

whether / if ve soru kelimeleri
Evet/hayır belirsizliği 'whether' veya 'if' ile verilir; ancak özne konumunda, edattan sonra, 'to V1' önünde ve 'or not' hemen ardından geldiğinde yalnızca 'whether' kullanılır. Soru kelimeleriyle (who, where, why, how, how much) başlayan isim cümleciklerinde söz dizimi soru değil DÜZ cümle düzenidir: 'I wonder where he lives' (where does he live değil).

Subjunctive ve 'the fact that'
'It is essential/vital/important that' ve 'suggest, recommend, insist, demand that' yapılarından sonra fiil yalın hâlde kalır: 'It is vital that every patient be informed.' Bir edattan sonra cümle getirmek gerektiğinde 'that' yerine 'the fact that' kullanılır: 'Despite the fact that...', 'due to the fact that...'.

Sonuç olarak, isim cümleciği sorularında boşluktan sonraki cümleye bakın: tam mı, eksik mi? Evet/hayır belirsizliği mi var, yoksa bir bilgi mi soruluyor? Söz dizimi düz mü, devrik mi? Dolaylı soru cümlesinde devrik yapı içeren seçenek her zaman yanlıştır.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-noun-clauses$ydsc$) AND "position" = 0;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Noun Clauses (İsim Cümlecikleri) – Konuya Giriş$ydsc$, 0, 8, $ydsc$İsim cümlecikleri bir cümlede özne, nesne ya da tümleç görevi gören yan cümlelerdir: 'What she said surprised me', 'I don't know whether he will come', 'The problem is that we have no data'. YDS'de bu konu en çok 'that / what / whether / if / soru kelimesi' seçimiyle ve dolaylı soru cümlesindeki söz dizimiyle test edilir.

that mi, what mi?
'that' anlam taşımaz; sadece bir cümleyi bağlar ve arkasından TAM bir cümle gelir: 'He said that the results were wrong.' 'what' ise 'şey/ne' anlamını kendi içinde taşır ve arkasından EKSİK bir cümle gelir (nesnesi ya da öznesi eksik): 'What surprised me was his answer.' Boşluktan sonraki cümlede bir öğe eksikse 'what', tamsa 'that' gerekir.

whether / if ve soru kelimeleri
Evet/hayır belirsizliği 'whether' veya 'if' ile verilir; ancak özne konumunda, edattan sonra, 'to V1' önünde ve 'or not' hemen ardından geldiğinde yalnızca 'whether' kullanılır. Soru kelimeleriyle (who, where, why, how, how much) başlayan isim cümleciklerinde söz dizimi soru değil DÜZ cümle düzenidir: 'I wonder where he lives' (where does he live değil).

Subjunctive ve 'the fact that'
'It is essential/vital/important that' ve 'suggest, recommend, insist, demand that' yapılarından sonra fiil yalın hâlde kalır: 'It is vital that every patient be informed.' Bir edattan sonra cümle getirmek gerektiğinde 'that' yerine 'the fact that' kullanılır: 'Despite the fact that...', 'due to the fact that...'.

Sonuç olarak, isim cümleciği sorularında boşluktan sonraki cümleye bakın: tam mı, eksik mi? Evet/hayır belirsizliği mi var, yoksa bir bilgi mi soruluyor? Söz dizimi düz mü, devrik mi? Dolaylı soru cümlesinde devrik yapı içeren seçenek her zaman yanlıştır.$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-noun-clauses$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 0);

UPDATE "topic_lessons" SET "title" = $ydsc$Noun Clauses (İsim Cümlecikleri) – Kurallar Referansı$ydsc$, "durationMinutes" = 12, "contentBody" = $ydsc$that + tam cümle – Bilinen/kesin bir bilgiyi bağlar; nesne konumunda düşürülebilir.
Örnek: "Studies show that sleep improves memory." (Çalışmalar uykunun hafızayı güçlendirdiğini gösteriyor.)

what + eksik cümle – '... şey' anlamı; cümlenin nesnesi veya öznesi eksiktir.
Örnek: "What the patients need most is regular care." (Hastaların en çok ihtiyaç duyduğu şey düzenli bakımdır.)

whether (or not) – Evet/hayır belirsizliği; özne konumunda, edattan sonra ve 'to V1' önünde zorunludur.
Örnek: "Whether the plan will work remains unclear." (Planın işe yarayıp yaramayacağı belirsizliğini koruyor.)

if (= whether) – Sadece nesne konumunda kullanılabilir.
Örnek: "The doctor asked if I had any allergies." (Doktor herhangi bir alerjim olup olmadığını sordu.)

Soru kelimesi + düz cümle – Dolaylı soruda söz dizimi devrik değil düzdür.
Örnek: "Scientists still don't know how the brain stores memories." (Bilim insanları beynin anıları nasıl depoladığını hâlâ bilmiyor.)

Soru kelimesi + to V1 – İsim cümleciğinin kısaltması.
Örnek: "The guide explains how to apply for a visa." (Rehber vizeye nasıl başvurulacağını açıklıyor.)

It + be + sıfat + that – Uzun özneyi sona atma.
Örnek: "It is surprising that so few people voted." (Bu kadar az kişinin oy kullanması şaşırtıcı.)

Subjunctive: it is vital/essential that + özne + V1 – Gereklilik bildiren sıfat ve fiillerden sonra fiil yalın kalır.
Örnek: "The committee recommended that the factory be closed." (Komite fabrikanın kapatılmasını önerdi.)

Edat + the fact that – Edattan sonra 'that' tek başına gelemez.
Örnek: "The study is limited by the fact that it used a small sample." (Çalışma küçük bir örneklem kullanmış olmasıyla sınırlıdır.)

whoever / whatever / wherever – 'Her kim/ne/nerede ise' anlamlı isim cümleciği.
Örnek: "Whoever finishes first can leave early." (Kim önce bitirirse erken çıkabilir.)

Dolaylı anlatımda zaman kaydırma – Geçmiş zamanlı ana fiilden sonra zaman bir adım geçmişe kayar.
Örnek: "She said that she had already sent the files." (Dosyaları çoktan gönderdiğini söyledi.)$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-noun-clauses$ydsc$) AND "position" = 1;

