WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-noun-clauses$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 1);

UPDATE "topic_lessons" SET "title" = $ydsc$Noun Clauses (İsim Cümlecikleri) – Örnek Sorular ve Çözümler$ydsc$, "durationMinutes" = 10, "contentBody" = $ydsc$Örnek 1: Örnek soru: "---- the new treatment is more effective than the old one has not yet been proven."
(A) That (B) What (C) If (D) Which
Doğru cevap (A) 'That' — Boşluktan sonra TAM bir cümle var ('the new treatment is more effective...'); bu yüzden 'what' elenir. Cümlecik özne konumunda olduğu için 'If' kullanılamaz. Kesin bir iddiayı bağlayan 'That' doğrudur.

Örnek 2: Örnek soru: "The manager couldn't explain ---- the shipment had been delayed for three weeks."
(A) that why (B) why (C) what (D) whether if
Doğru cevap (B) 'why' — Bir nedeni soran dolaylı soru var ve arkasından tam cümle geliyor; doğru bağlayıcı 'why'dır. 'what' eksik cümle ister, diğer iki seçenek ise iki bağlacı yan yana kullanarak yapıyı bozar.

Örnek 3: Örnek soru: "There is still a debate about ---- antibiotics should be given to children with mild infections."
(A) if (B) that (C) whether (D) what
Doğru cevap (C) 'whether' — Boşluk bir edattan ('about') sonra geliyor ve evet/hayır belirsizliği anlatılıyor; edattan sonra 'if' kullanılamaz, yalnızca 'whether' kullanılır. 'that' ise edattan sonra tek başına gelemez.

Örnek 4: Örnek soru: "Experts insist that every new building ---- to withstand strong earthquakes."
(A) is designed (B) be designed (C) was designed (D) will be designed
Doğru cevap (B) 'be designed' — 'insist that' yapısından sonra subjunctive kullanılır ve fiil, özne tekil olsa da yalın hâlde kalır; edilgen anlam 'be designed' ile verilir.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-noun-clauses$ydsc$) AND "position" = 2;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Noun Clauses (İsim Cümlecikleri) – Örnek Sorular ve Çözümler$ydsc$, 2, 10, $ydsc$Örnek 1: Örnek soru: "---- the new treatment is more effective than the old one has not yet been proven."
(A) That (B) What (C) If (D) Which
Doğru cevap (A) 'That' — Boşluktan sonra TAM bir cümle var ('the new treatment is more effective...'); bu yüzden 'what' elenir. Cümlecik özne konumunda olduğu için 'If' kullanılamaz. Kesin bir iddiayı bağlayan 'That' doğrudur.

Örnek 2: Örnek soru: "The manager couldn't explain ---- the shipment had been delayed for three weeks."
(A) that why (B) why (C) what (D) whether if
Doğru cevap (B) 'why' — Bir nedeni soran dolaylı soru var ve arkasından tam cümle geliyor; doğru bağlayıcı 'why'dır. 'what' eksik cümle ister, diğer iki seçenek ise iki bağlacı yan yana kullanarak yapıyı bozar.

Örnek 3: Örnek soru: "There is still a debate about ---- antibiotics should be given to children with mild infections."
(A) if (B) that (C) whether (D) what
Doğru cevap (C) 'whether' — Boşluk bir edattan ('about') sonra geliyor ve evet/hayır belirsizliği anlatılıyor; edattan sonra 'if' kullanılamaz, yalnızca 'whether' kullanılır. 'that' ise edattan sonra tek başına gelemez.

Örnek 4: Örnek soru: "Experts insist that every new building ---- to withstand strong earthquakes."
(A) is designed (B) be designed (C) was designed (D) will be designed
Doğru cevap (B) 'be designed' — 'insist that' yapısından sonra subjunctive kullanılır ve fiil, özne tekil olsa da yalın hâlde kalır; edilgen anlam 'be designed' ile verilir.$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-noun-clauses$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 2);

INSERT INTO "exam_topics" ("id", "examTypeId", "name", "slug", "questionCount", "difficulty", "displayOrder", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, id, $ydsc$Adverbial Clauses (Zarf Cümlecikleri)$ydsc$, $ydsc$gramer-adverbial-clauses$ydsc$, NULL, $ydsc$Orta$ydsc$, 13, now(), now() FROM "exam_types" WHERE "code" = 'YDS'
ON CONFLICT ("examTypeId", "slug") DO UPDATE SET "name" = EXCLUDED."name", "questionCount" = EXCLUDED."questionCount", "difficulty" = EXCLUDED."difficulty", "displayOrder" = EXCLUDED."displayOrder", "updatedAt" = now();

UPDATE "topic_lessons" SET "title" = $ydsc$Adverbial Clauses (Zarf Cümlecikleri) – Konuya Giriş$ydsc$, "durationMinutes" = 8, "contentBody" = $ydsc$Zarf cümlecikleri ana cümlenin zamanını, nedenini, koşulunu, amacını, sonucunu ya da zıtlığını anlatan yan cümlelerdir. YDS'de bağlaç sorularıyla iç içe test edilirler; ancak bu konuda ek olarak zaman uyumu (tense harmony) ve zaman bağlaçlarından sonra gelecek zaman kullanılmaması kuralı da sorulur.

Zaman bildiren zarf cümlecikleri
'when, while, as, before, after, until, by the time, as soon as, once, since, whenever' zaman bağlaçlarıdır. Bu bağlaçlardan sonra gelecek anlamı 'will' ile değil, Present Simple ya da Present Perfect ile verilir: 'I will call you as soon as I arrive.' 'by the time' ana cümlede genellikle perfect zaman (had V3 / will have V3) ister; 'since' ise ana cümlede Present Perfect ister.

Zaman uyumu
Ana cümle ile yan cümle aynı zaman dilimini paylaşmalıdır. Geçmişte iki eylemden önce olan Past Perfect, sonra olan Past Simple ile anlatılır; devam eden bir eylemi kesen eylem Past Simple, kesilen eylem Past Continuous olur. Seçeneklerden biri bu uyumu bozuyorsa (ör. ana cümle geçmiş, yan cümle gelecek) anlamına bakmadan elenebilir.

Neden, amaç, sonuç ve zıtlık
'because, since, as, now that' neden; 'so that, in order that' amaç; 'so ... that, such ... that' sonuç; 'although, even though, while, whereas' zıtlık bildirir. 'now that' (-dığına göre, artık) yeni bir durumun sonucunu anlatır; 'as long as / provided that / unless' ise koşul cümleleri başlığında ayrıntılı ele alınır.

Sonuç olarak, zarf cümleciği sorularında hem bağlacın anlamını hem de iki cümlenin zaman uyumunu kontrol edin. Özellikle 'by the time, until, since, as soon as' içeren sorularda doğru cevap çoğu zaman seçeneklerdeki zaman bilgisine bakılarak bulunur.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-adverbial-clauses$ydsc$) AND "position" = 0;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Adverbial Clauses (Zarf Cümlecikleri) – Konuya Giriş$ydsc$, 0, 8, $ydsc$Zarf cümlecikleri ana cümlenin zamanını, nedenini, koşulunu, amacını, sonucunu ya da zıtlığını anlatan yan cümlelerdir. YDS'de bağlaç sorularıyla iç içe test edilirler; ancak bu konuda ek olarak zaman uyumu (tense harmony) ve zaman bağlaçlarından sonra gelecek zaman kullanılmaması kuralı da sorulur.

Zaman bildiren zarf cümlecikleri
'when, while, as, before, after, until, by the time, as soon as, once, since, whenever' zaman bağlaçlarıdır. Bu bağlaçlardan sonra gelecek anlamı 'will' ile değil, Present Simple ya da Present Perfect ile verilir: 'I will call you as soon as I arrive.' 'by the time' ana cümlede genellikle perfect zaman (had V3 / will have V3) ister; 'since' ise ana cümlede Present Perfect ister.

Zaman uyumu
Ana cümle ile yan cümle aynı zaman dilimini paylaşmalıdır. Geçmişte iki eylemden önce olan Past Perfect, sonra olan Past Simple ile anlatılır; devam eden bir eylemi kesen eylem Past Simple, kesilen eylem Past Continuous olur. Seçeneklerden biri bu uyumu bozuyorsa (ör. ana cümle geçmiş, yan cümle gelecek) anlamına bakmadan elenebilir.

Neden, amaç, sonuç ve zıtlık
'because, since, as, now that' neden; 'so that, in order that' amaç; 'so ... that, such ... that' sonuç; 'although, even though, while, whereas' zıtlık bildirir. 'now that' (-dığına göre, artık) yeni bir durumun sonucunu anlatır; 'as long as / provided that / unless' ise koşul cümleleri başlığında ayrıntılı ele alınır.

Sonuç olarak, zarf cümleciği sorularında hem bağlacın anlamını hem de iki cümlenin zaman uyumunu kontrol edin. Özellikle 'by the time, until, since, as soon as' içeren sorularda doğru cevap çoğu zaman seçeneklerdeki zaman bilgisine bakılarak bulunur.$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-adverbial-clauses$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 0);

UPDATE "topic_lessons" SET "title" = $ydsc$Adverbial Clauses (Zarf Cümlecikleri) – Kurallar Referansı$ydsc$, "durationMinutes" = 12, "contentBody" = $ydsc$when / while / as – 'when' bir an, 'while/as' devam eden süreç; 'as' ayrıca 'çünkü' anlamı taşıyabilir.
Örnek: "While the engineers were testing the system, the power went out." (Mühendisler sistemi test ederken elektrik kesildi.)

Zaman bağlacından sonra 'will' kullanılmaz – Gelecek anlamı Present Simple / Present Perfect ile verilir.
Örnek: "We will start the meeting as soon as the director arrives." (Müdür gelir gelmez toplantıya başlayacağız.)

by the time + Past Simple → had V3 – Geçmişte bir andan önce tamamlanmış eylem.
Örnek: "By the time the ambulance arrived, the patient had lost consciousness." (Ambulans geldiğinde hasta bilincini kaybetmişti.)

by the time + Present Simple → will have V3 – Gelecekte bir andan önce tamamlanmış olacak eylem.
Örnek: "By the time you read this, I will have left the country." (Sen bunu okuduğunda ben ülkeden ayrılmış olacağım.)

since + Past Simple → Present Perfect – Geçmişte başlayıp süren durum.
Örnek: "The town has grown rapidly since the factory opened." (Fabrika açıldığından beri kasaba hızla büyüdü.)

until / till – -e kadar; olumsuz ana cümleyle 'ancak ...dığında'.
Örnek: "The results will not be published until the review is complete." (Sonuçlar inceleme tamamlanana kadar yayımlanmayacak.)

once / as soon as / the moment – -ir -mez, -dıktan hemen sonra.
Örnek: "Once the data is collected, it will be analysed." (Veriler toplandıktan sonra analiz edilecek.)

now that – -dığına göre, artık ... olduğu için.
Örnek: "Now that the exams are over, students can relax." (Sınavlar bittiğine göre öğrenciler rahatlayabilir.)

as / since (neden) – -dığı için; neden çoğunlukla bilinen bir durumdur.
Örnek: "As the road was closed, we took another route." (Yol kapalı olduğu için başka bir güzergâh kullandık.)

so ... that / such ... that – O kadar ... ki (sonuç).
Örnek: "It was such a difficult test that nobody finished on time." (O kadar zor bir sınavdı ki kimse zamanında bitiremedi.)

even though / while (zıtlık) – -e rağmen; 'while' cümle başında zıtlık da bildirir.
Örnek: "While the idea is attractive, it is too expensive to implement." (Fikir çekici olsa da uygulanması çok pahalı.)

whenever / every time – Her ne zaman ki, her defasında.
Örnek: "Whenever the temperature drops below zero, the pipes freeze." (Sıcaklık sıfırın altına her düştüğünde borular donar.)$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-adverbial-clauses$ydsc$) AND "position" = 1;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Adverbial Clauses (Zarf Cümlecikleri) – Kurallar Referansı$ydsc$, 1, 12, $ydsc$when / while / as – 'when' bir an, 'while/as' devam eden süreç; 'as' ayrıca 'çünkü' anlamı taşıyabilir.
Örnek: "While the engineers were testing the system, the power went out." (Mühendisler sistemi test ederken elektrik kesildi.)

Zaman bağlacından sonra 'will' kullanılmaz – Gelecek anlamı Present Simple / Present Perfect ile verilir.
Örnek: "We will start the meeting as soon as the director arrives." (Müdür gelir gelmez toplantıya başlayacağız.)

by the time + Past Simple → had V3 – Geçmişte bir andan önce tamamlanmış eylem.
Örnek: "By the time the ambulance arrived, the patient had lost consciousness." (Ambulans geldiğinde hasta bilincini kaybetmişti.)

by the time + Present Simple → will have V3 – Gelecekte bir andan önce tamamlanmış olacak eylem.
Örnek: "By the time you read this, I will have left the country." (Sen bunu okuduğunda ben ülkeden ayrılmış olacağım.)

since + Past Simple → Present Perfect – Geçmişte başlayıp süren durum.
Örnek: "The town has grown rapidly since the factory opened." (Fabrika açıldığından beri kasaba hızla büyüdü.)

until / till – -e kadar; olumsuz ana cümleyle 'ancak ...dığında'.
Örnek: "The results will not be published until the review is complete." (Sonuçlar inceleme tamamlanana kadar yayımlanmayacak.)

once / as soon as / the moment – -ir -mez, -dıktan hemen sonra.
Örnek: "Once the data is collected, it will be analysed." (Veriler toplandıktan sonra analiz edilecek.)

now that – -dığına göre, artık ... olduğu için.
Örnek: "Now that the exams are over, students can relax." (Sınavlar bittiğine göre öğrenciler rahatlayabilir.)

as / since (neden) – -dığı için; neden çoğunlukla bilinen bir durumdur.
Örnek: "As the road was closed, we took another route." (Yol kapalı olduğu için başka bir güzergâh kullandık.)

so ... that / such ... that – O kadar ... ki (sonuç).
Örnek: "It was such a difficult test that nobody finished on time." (O kadar zor bir sınavdı ki kimse zamanında bitiremedi.)

even though / while (zıtlık) – -e rağmen; 'while' cümle başında zıtlık da bildirir.
Örnek: "While the idea is attractive, it is too expensive to implement." (Fikir çekici olsa da uygulanması çok pahalı.)

whenever / every time – Her ne zaman ki, her defasında.
Örnek: "Whenever the temperature drops below zero, the pipes freeze." (Sıcaklık sıfırın altına her düştüğünde borular donar.)$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-adverbial-clauses$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 1);

UPDATE "topic_lessons" SET "title" = $ydsc$Adverbial Clauses (Zarf Cümlecikleri) – Örnek Sorular ve Çözümler$ydsc$, "durationMinutes" = 10, "contentBody" = $ydsc$Örnek 1: Örnek soru: "The new hospital wing will open to patients as soon as the safety inspection ----."
(A) will be completed (B) is completed (C) was completed (D) would be completed
Doğru cevap (B) 'is completed' — 'as soon as' bir zaman bağlacıdır ve gelecek anlamlı cümlelerde ardından 'will' kullanılmaz; gelecek anlamı Present Simple ile verilir. Denetim kendini tamamlamadığı için edilgen 'is completed' doğrudur.

Örnek 2: Örnek soru: "By the time the rescue team reached the village, most of the residents ---- to safer areas."
(A) moved (B) have moved (C) had moved (D) would move
Doğru cevap (C) 'had moved' — 'By the time + Past Simple' yapısı, ana cümlede o andan ÖNCE tamamlanmış bir eylem ister; geçmişteki önceliği Past Perfect 'had moved' verir.

Örnek 3: Örnek soru: "---- the company introduced flexible working hours, staff turnover has fallen by nearly 30%."
(A) Until (B) Since (C) By the time (D) While
Doğru cevap (B) 'Since' — Ana cümle Present Perfect ('has fallen') ve yan cümle geçmişteki bir başlangıç noktası ('introduced') içeriyor; geçmişte başlayıp bugüne uzanan süre 'Since' ile kurulur.

Örnek 4: Örnek soru: "---- most of the population now lives in cities, rural schools are struggling to stay open."
(A) Unless (B) Now that (C) So that (D) Even if
Doğru cevap (B) 'Now that' — Nüfusun çoğunun artık şehirlerde yaşaması, kırsal okulların zorlanmasının NEDENİDİR ve yeni bir durumu anlatır; bu anlam 'Now that' (-dığına göre, artık) ile verilir.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-adverbial-clauses$ydsc$) AND "position" = 2;

