SELECT gen_random_uuid()::text, id, $ydsc$Conditionals ve Wish Clauses$ydsc$, $ydsc$gramer-conditionals-wish$ydsc$, NULL, $ydsc$Orta$ydsc$, 14, now(), now() FROM "exam_types" WHERE "code" = 'YDS'
ON CONFLICT ("examTypeId", "slug") DO UPDATE SET "name" = EXCLUDED."name", "questionCount" = EXCLUDED."questionCount", "difficulty" = EXCLUDED."difficulty", "displayOrder" = EXCLUDED."displayOrder", "updatedAt" = now();

UPDATE "topic_lessons" SET "title" = $ydsc$Conditionals ve Wish Clauses – Konuya Giriş$ydsc$, "durationMinutes" = 8, "contentBody" = $ydsc$Koşul cümleleri ve dilek (wish) cümleleri, gerçekleşmiş ya da gerçekleşmemiş durumları anlatır ve YDS'de en düzenli çıkan konulardan biridir. Bu sorularda anahtar, koşulun GERÇEK mi yoksa HAYALİ mi olduğunu ve hangi zamana ait olduğunu belirlemektir; doğru kalıp bu iki bilgiden çıkar.

Dört temel koşul tipi
Type 0 (genel gerçek): If + Present, Present. Type 1 (gerçek gelecek olasılığı): If + Present, will V1. Type 2 (şimdiki zamana dair hayali durum): If + Past, would V1. Type 3 (geçmişe dair hayali durum): If + Past Perfect, would have V3. Karışık (mixed) koşullarda geçmişteki bir durumun bugünkü sonucu anlatılır: If + had V3, would V1.

Devrik koşul ve 'if' yerine geçenler
Resmi metinlerde 'if' düşürülüp yardımcı fiil başa alınır: 'Had we known...' (= If we had known), 'Were it not for...' (= If it were not for), 'Should you need help...' (= If you should need help). 'unless' = if not; 'provided/providing that, as long as, on condition that' yalnızca ... şartıyla; 'in case' olasılığa karşı önlem; 'otherwise' aksi hâlde anlamı verir.

Wish ve if only
Bugünle ilgili pişmanlık 'wish + Past', geçmişle ilgili pişmanlık 'wish + Past Perfect', başkasının davranışından şikâyet ve gelecekle ilgili istek 'wish + would V1' ile kurulur. 'It's (high) time + Past' (artık ... zamanı geldi), 'would rather + özne + Past' (birinin bir şey yapmasını tercih etmek) ve 'as if / as though + Past' (sanki) de aynı 'hayali geçmiş' mantığıyla çalışır.

Sonuç olarak, bir koşul sorusunda önce cümlenin hangi zamandan bahsettiğini, sonra gerçek mi hayali mi olduğunu belirleyin. Cümlenin devamında 'but he didn't', 'but it is too late' gibi ifadeler hayali bir geçmişi, 'tomorrow, next week' gibi ifadeler gerçek bir gelecek olasılığını işaret eder.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-conditionals-wish$ydsc$) AND "position" = 0;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Conditionals ve Wish Clauses – Konuya Giriş$ydsc$, 0, 8, $ydsc$Koşul cümleleri ve dilek (wish) cümleleri, gerçekleşmiş ya da gerçekleşmemiş durumları anlatır ve YDS'de en düzenli çıkan konulardan biridir. Bu sorularda anahtar, koşulun GERÇEK mi yoksa HAYALİ mi olduğunu ve hangi zamana ait olduğunu belirlemektir; doğru kalıp bu iki bilgiden çıkar.

Dört temel koşul tipi
Type 0 (genel gerçek): If + Present, Present. Type 1 (gerçek gelecek olasılığı): If + Present, will V1. Type 2 (şimdiki zamana dair hayali durum): If + Past, would V1. Type 3 (geçmişe dair hayali durum): If + Past Perfect, would have V3. Karışık (mixed) koşullarda geçmişteki bir durumun bugünkü sonucu anlatılır: If + had V3, would V1.

Devrik koşul ve 'if' yerine geçenler
Resmi metinlerde 'if' düşürülüp yardımcı fiil başa alınır: 'Had we known...' (= If we had known), 'Were it not for...' (= If it were not for), 'Should you need help...' (= If you should need help). 'unless' = if not; 'provided/providing that, as long as, on condition that' yalnızca ... şartıyla; 'in case' olasılığa karşı önlem; 'otherwise' aksi hâlde anlamı verir.

Wish ve if only
Bugünle ilgili pişmanlık 'wish + Past', geçmişle ilgili pişmanlık 'wish + Past Perfect', başkasının davranışından şikâyet ve gelecekle ilgili istek 'wish + would V1' ile kurulur. 'It's (high) time + Past' (artık ... zamanı geldi), 'would rather + özne + Past' (birinin bir şey yapmasını tercih etmek) ve 'as if / as though + Past' (sanki) de aynı 'hayali geçmiş' mantığıyla çalışır.

Sonuç olarak, bir koşul sorusunda önce cümlenin hangi zamandan bahsettiğini, sonra gerçek mi hayali mi olduğunu belirleyin. Cümlenin devamında 'but he didn't', 'but it is too late' gibi ifadeler hayali bir geçmişi, 'tomorrow, next week' gibi ifadeler gerçek bir gelecek olasılığını işaret eder.$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-conditionals-wish$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 0);

UPDATE "topic_lessons" SET "title" = $ydsc$Conditionals ve Wish Clauses – Kurallar Referansı$ydsc$, "durationMinutes" = 12, "contentBody" = $ydsc$Type 0: If + Present, Present – Bilimsel ve genel gerçekler.
Örnek: "If you heat ice, it melts." (Buzu ısıtırsanız erir.)

Type 1: If + Present, will V1 – Gelecekte gerçekleşmesi olası durum.
Örnek: "If the rain continues, the river will flood." (Yağmur devam ederse nehir taşacak.)

Type 2: If + Past, would V1 – Şimdiye dair hayali/gerçek dışı durum; 'be' için 'were'.
Örnek: "If I were the minister, I would invest more in education." (Bakan ben olsaydım eğitime daha çok yatırım yapardım.)

Type 3: If + had V3, would have V3 – Geçmişte gerçekleşmemiş durum ve sonucu.
Örnek: "If the warning had been issued earlier, fewer people would have been injured." (Uyarı daha erken yapılsaydı daha az kişi yaralanırdı.)

Mixed: If + had V3, would V1 – Geçmişteki bir durumun bugünkü sonucu.
Örnek: "If she had accepted the job, she would be living in London now." (İşi kabul etseydi şimdi Londra'da yaşıyor olurdu.)

unless = if not – -mezse; kendisi olumlu anlam taşır, olumsuz fiil almaz.
Örnek: "The project will fail unless it receives more funding." (Daha fazla fon almazsa proje başarısız olacak.)

provided that / as long as / on condition that – Yalnızca ... şartıyla.
Örnek: "You can borrow the car as long as you return it by Friday." (Cumaya kadar geri getirmen şartıyla arabayı ödünç alabilirsin.)

Devrik koşul: Had / Were / Should – 'if' düşer, yardımcı fiil başa gelir.
Örnek: "Had the bridge been inspected, the accident could have been prevented." (Köprü denetlenmiş olsaydı kaza önlenebilirdi.)

but for / without + isim – Olmasaydı (Type 2 veya 3 ile).
Örnek: "But for your help, we would never have finished on time." (Senin yardımın olmasaydı asla zamanında bitiremezdik.)

wish / if only + Past – Bugüne dair pişmanlık veya istek.
Örnek: "I wish I had more time to read." (Keşke okumak için daha çok vaktim olsa.)

wish / if only + had V3 – Geçmişe dair pişmanlık.
Örnek: "He wishes he had studied medicine instead of law." (Hukuk yerine tıp okumuş olmayı diliyor.)

wish + would V1 – Başkasının davranışından şikâyet; gelecekte değişiklik isteği.
Örnek: "I wish my neighbours would stop making so much noise." (Keşke komşularım bu kadar gürültü yapmayı bıraksa.)

It's (high) time + Past / as if + Past – Artık ... vakti geldi / sanki.
Örnek: "It's high time the government took action on pollution." (Hükümetin kirlilik konusunda harekete geçmesinin vakti çoktan geldi.)$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-conditionals-wish$ydsc$) AND "position" = 1;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Conditionals ve Wish Clauses – Kurallar Referansı$ydsc$, 1, 12, $ydsc$Type 0: If + Present, Present – Bilimsel ve genel gerçekler.
Örnek: "If you heat ice, it melts." (Buzu ısıtırsanız erir.)

Type 1: If + Present, will V1 – Gelecekte gerçekleşmesi olası durum.
Örnek: "If the rain continues, the river will flood." (Yağmur devam ederse nehir taşacak.)

Type 2: If + Past, would V1 – Şimdiye dair hayali/gerçek dışı durum; 'be' için 'were'.
Örnek: "If I were the minister, I would invest more in education." (Bakan ben olsaydım eğitime daha çok yatırım yapardım.)

Type 3: If + had V3, would have V3 – Geçmişte gerçekleşmemiş durum ve sonucu.
Örnek: "If the warning had been issued earlier, fewer people would have been injured." (Uyarı daha erken yapılsaydı daha az kişi yaralanırdı.)

Mixed: If + had V3, would V1 – Geçmişteki bir durumun bugünkü sonucu.
Örnek: "If she had accepted the job, she would be living in London now." (İşi kabul etseydi şimdi Londra'da yaşıyor olurdu.)

unless = if not – -mezse; kendisi olumlu anlam taşır, olumsuz fiil almaz.
Örnek: "The project will fail unless it receives more funding." (Daha fazla fon almazsa proje başarısız olacak.)

provided that / as long as / on condition that – Yalnızca ... şartıyla.
Örnek: "You can borrow the car as long as you return it by Friday." (Cumaya kadar geri getirmen şartıyla arabayı ödünç alabilirsin.)

Devrik koşul: Had / Were / Should – 'if' düşer, yardımcı fiil başa gelir.
Örnek: "Had the bridge been inspected, the accident could have been prevented." (Köprü denetlenmiş olsaydı kaza önlenebilirdi.)

but for / without + isim – Olmasaydı (Type 2 veya 3 ile).
Örnek: "But for your help, we would never have finished on time." (Senin yardımın olmasaydı asla zamanında bitiremezdik.)

wish / if only + Past – Bugüne dair pişmanlık veya istek.
Örnek: "I wish I had more time to read." (Keşke okumak için daha çok vaktim olsa.)

wish / if only + had V3 – Geçmişe dair pişmanlık.
Örnek: "He wishes he had studied medicine instead of law." (Hukuk yerine tıp okumuş olmayı diliyor.)

wish + would V1 – Başkasının davranışından şikâyet; gelecekte değişiklik isteği.
Örnek: "I wish my neighbours would stop making so much noise." (Keşke komşularım bu kadar gürültü yapmayı bıraksa.)

It's (high) time + Past / as if + Past – Artık ... vakti geldi / sanki.
Örnek: "It's high time the government took action on pollution." (Hükümetin kirlilik konusunda harekete geçmesinin vakti çoktan geldi.)$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-conditionals-wish$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 1);

UPDATE "topic_lessons" SET "title" = $ydsc$Conditionals ve Wish Clauses – Örnek Sorular ve Çözümler$ydsc$, "durationMinutes" = 10, "contentBody" = $ydsc$Örnek 1: Örnek soru: "If the city ---- more bicycle lanes ten years ago, traffic would not be so heavy today."
(A) builds (B) built (C) had built (D) would build
Doğru cevap (C) 'had built' — Koşul geçmişe ait ('ten years ago'), sonuç ise bugüne ait ('today'); bu bir mixed conditional'dır. Geçmişteki gerçekleşmemiş koşul Past Perfect 'had built' ile kurulur.

Örnek 2: Örnek soru: "---- the pilot not reacted so quickly, the plane would have crashed into the mountain."
(A) Unless (B) Had (C) If (D) Were
Doğru cevap (B) 'Had' — Cümlenin sonu 'would have crashed' ile geçmişe ait hayali bir sonucu anlatıyor (Type 3). 'if' düşürülüp yardımcı fiil başa alınınca devrik koşul 'Had + özne + not + V3' olur. 'If' ve 'Unless' bu söz dizimiyle (özne + not + V3) kullanılamaz, 'Were' ise Type 2'ye aittir.

Örnek 3: Örnek soru: "The patient will make a full recovery ---- she follows the doctor's instructions carefully."
(A) unless (B) provided that (C) in case (D) otherwise
Doğru cevap (B) 'provided that' — İyileşme, talimatlara uyulması ŞARTINA bağlı; bu anlam 'provided that' ile verilir. 'unless' anlamı tersine çevirir, 'in case' önlem bildirir, 'otherwise' ise cümle zarfıdır ve iki cümleyi bu biçimde bağlayamaz.

Örnek 4: Örnek soru: "Looking at the damage, the owner wishes he ---- the house before the storm season began."
(A) insured (B) would insure (C) had insured (D) has insured
Doğru cevap (C) 'had insured' — Pişmanlık geçmişteki bir eyleme ait (fırtına sezonu başlamadan önce sigortalatmak); geçmişe yönelik 'wish' Past Perfect 'had insured' ile kurulur.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-conditionals-wish$ydsc$) AND "position" = 2;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Conditionals ve Wish Clauses – Örnek Sorular ve Çözümler$ydsc$, 2, 10, $ydsc$Örnek 1: Örnek soru: "If the city ---- more bicycle lanes ten years ago, traffic would not be so heavy today."
(A) builds (B) built (C) had built (D) would build
Doğru cevap (C) 'had built' — Koşul geçmişe ait ('ten years ago'), sonuç ise bugüne ait ('today'); bu bir mixed conditional'dır. Geçmişteki gerçekleşmemiş koşul Past Perfect 'had built' ile kurulur.

Örnek 2: Örnek soru: "---- the pilot not reacted so quickly, the plane would have crashed into the mountain."
(A) Unless (B) Had (C) If (D) Were
Doğru cevap (B) 'Had' — Cümlenin sonu 'would have crashed' ile geçmişe ait hayali bir sonucu anlatıyor (Type 3). 'if' düşürülüp yardımcı fiil başa alınınca devrik koşul 'Had + özne + not + V3' olur. 'If' ve 'Unless' bu söz dizimiyle (özne + not + V3) kullanılamaz, 'Were' ise Type 2'ye aittir.

Örnek 3: Örnek soru: "The patient will make a full recovery ---- she follows the doctor's instructions carefully."
(A) unless (B) provided that (C) in case (D) otherwise
Doğru cevap (B) 'provided that' — İyileşme, talimatlara uyulması ŞARTINA bağlı; bu anlam 'provided that' ile verilir. 'unless' anlamı tersine çevirir, 'in case' önlem bildirir, 'otherwise' ise cümle zarfıdır ve iki cümleyi bu biçimde bağlayamaz.

Örnek 4: Örnek soru: "Looking at the damage, the owner wishes he ---- the house before the storm season began."
(A) insured (B) would insure (C) had insured (D) has insured
Doğru cevap (C) 'had insured' — Pişmanlık geçmişteki bir eyleme ait (fırtına sezonu başlamadan önce sigortalatmak); geçmişe yönelik 'wish' Past Perfect 'had insured' ile kurulur.$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-conditionals-wish$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 2);

