WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-karma$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 1);

UPDATE "topic_lessons" SET "title" = $ydsc$Karma Soru ve Metin Çalışmaları – Örnek Sorular ve Çözümler$ydsc$, "durationMinutes" = 10, "contentBody" = $ydsc$Örnek 1: Örnek soru: "The new bridge, ---- construction ---- in 2019, is expected to reduce travel time by half."
(A) which / started (B) whose / began (C) that / was begun (D) where / has begun
Doğru cevap (B) 'whose / began' — Boşluktan sonra bir isim ('construction') geliyor ve 'köprünün yapımı' anlamında iyelik var; bu yüzden 'whose'. İnşaat 2019'da BAŞLADI; 'begin' burada geçişsiz kullanıldığı ve geçmişte belirli bir zaman olduğu için 'began' doğrudur.

Örnek 2: Örnek soru: "---- the factory was closed last year, unemployment in the town ---- by nearly 12%."
(A) Since / has risen (B) Although / rose (C) Because / has been risen (D) Unless / rises
Doğru cevap (A) 'Since / has risen' — Ana cümle bugüne uzanan bir sonucu anlatıyor ve yan cümle geçmişteki başlangıç noktasını veriyor: 'Since + Past Simple, Present Perfect'. 'rise' geçişsiz olduğu için edilgen olamaz; 'Although' ise zıtlık bildirdiği için anlamca uymaz.

Örnek 3: Örnek soru: "If the patient ---- to hospital earlier, the doctors ---- the infection more easily."
(A) was taken / can treat (B) had been taken / could have treated (C) has been taken / would treat (D) were taken / had treated
Doğru cevap (B) 'had been taken / could have treated' — Geçmişte gerçekleşmemiş bir koşul ve sonucu anlatılıyor (Type 3). Hasta hastaneye götürüldüğü için koşul kısmı edilgen Past Perfect 'had been taken', sonuç kısmı 'could have treated' olur.

Örnek 4: Örnek soru: "Researchers are trying to find out ---- the ancient city was abandoned so suddenly."
(A) that (B) why (C) which (D) what
Doğru cevap (B) 'why' — Boşluktan sonra tam bir cümle var ve bir NEDEN sorgulanıyor; dolaylı soru 'why' ile kurulur. 'what' eksik cümle ister, 'that' bir belirsizlik bildirmez.

Örnek 5: Örnek soru: "---- in the 1950s, the theory was ignored for decades before it ---- by later studies."
(A) Proposing / confirmed (B) Proposed / was confirmed (C) Having proposed / had confirmed (D) To propose / has been confirmed
Doğru cevap (B) 'Proposed / was confirmed' — Teori ÖNERİLEN şeydir (edilgen kısaltma 'Proposed'); sonraki çalışmalar tarafından DOĞRULANMIŞTIR (edilgen 'was confirmed'). Etken seçenekler teoriyi eylemi yapan konumuna koyduğu için yanlıştır.

Örnek 6: Örnek soru: "The company not only reduced its prices ---- extended its warranty period, ---- sales doubled within a year."
(A) and also / so (B) but also / and as a result (C) or / because (D) as well / therefore
Doğru cevap (B) 'but also / and as a result' — 'not only' eşli bağlacı 'but also' ile tamamlanır. İkinci boşluk, fiyat indirimi ve garanti uzatmanın SONUCUNU bağlıyor; iki cümleyi virgülden sonra bağlayabilen sonuç ifadesi 'and as a result'tır. 'therefore' tek başına virgülle iki cümleyi bağlayamaz.$ydsc$, "contentBodyEn" = NULL, "updatedAt" = now()
WHERE "topicId" = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-karma$ydsc$) AND "position" = 2;

INSERT INTO "topic_lessons" ("id", "topicId", "title", "position", "durationMinutes", "contentBody", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, t.id, $ydsc$Karma Soru ve Metin Çalışmaları – Örnek Sorular ve Çözümler$ydsc$, 2, 10, $ydsc$Örnek 1: Örnek soru: "The new bridge, ---- construction ---- in 2019, is expected to reduce travel time by half."
(A) which / started (B) whose / began (C) that / was begun (D) where / has begun
Doğru cevap (B) 'whose / began' — Boşluktan sonra bir isim ('construction') geliyor ve 'köprünün yapımı' anlamında iyelik var; bu yüzden 'whose'. İnşaat 2019'da BAŞLADI; 'begin' burada geçişsiz kullanıldığı ve geçmişte belirli bir zaman olduğu için 'began' doğrudur.

Örnek 2: Örnek soru: "---- the factory was closed last year, unemployment in the town ---- by nearly 12%."
(A) Since / has risen (B) Although / rose (C) Because / has been risen (D) Unless / rises
Doğru cevap (A) 'Since / has risen' — Ana cümle bugüne uzanan bir sonucu anlatıyor ve yan cümle geçmişteki başlangıç noktasını veriyor: 'Since + Past Simple, Present Perfect'. 'rise' geçişsiz olduğu için edilgen olamaz; 'Although' ise zıtlık bildirdiği için anlamca uymaz.

Örnek 3: Örnek soru: "If the patient ---- to hospital earlier, the doctors ---- the infection more easily."
(A) was taken / can treat (B) had been taken / could have treated (C) has been taken / would treat (D) were taken / had treated
Doğru cevap (B) 'had been taken / could have treated' — Geçmişte gerçekleşmemiş bir koşul ve sonucu anlatılıyor (Type 3). Hasta hastaneye götürüldüğü için koşul kısmı edilgen Past Perfect 'had been taken', sonuç kısmı 'could have treated' olur.

Örnek 4: Örnek soru: "Researchers are trying to find out ---- the ancient city was abandoned so suddenly."
(A) that (B) why (C) which (D) what
Doğru cevap (B) 'why' — Boşluktan sonra tam bir cümle var ve bir NEDEN sorgulanıyor; dolaylı soru 'why' ile kurulur. 'what' eksik cümle ister, 'that' bir belirsizlik bildirmez.

Örnek 5: Örnek soru: "---- in the 1950s, the theory was ignored for decades before it ---- by later studies."
(A) Proposing / confirmed (B) Proposed / was confirmed (C) Having proposed / had confirmed (D) To propose / has been confirmed
Doğru cevap (B) 'Proposed / was confirmed' — Teori ÖNERİLEN şeydir (edilgen kısaltma 'Proposed'); sonraki çalışmalar tarafından DOĞRULANMIŞTIR (edilgen 'was confirmed'). Etken seçenekler teoriyi eylemi yapan konumuna koyduğu için yanlıştır.

Örnek 6: Örnek soru: "The company not only reduced its prices ---- extended its warranty period, ---- sales doubled within a year."
(A) and also / so (B) but also / and as a result (C) or / because (D) as well / therefore
Doğru cevap (B) 'but also / and as a result' — 'not only' eşli bağlacı 'but also' ile tamamlanır. İkinci boşluk, fiyat indirimi ve garanti uzatmanın SONUCUNU bağlıyor; iki cümleyi virgülden sonra bağlayabilen sonuç ifadesi 'and as a result'tır. 'therefore' tek başına virgülle iki cümleyi bağlayamaz.$ydsc$, now(), now() FROM "exam_topics" t
WHERE t.id = (SELECT id FROM "exam_topics" WHERE "examTypeId" = (SELECT id FROM "exam_types" WHERE "code" = 'YDS') AND "slug" = $ydsc$gramer-karma$ydsc$) AND NOT EXISTS (SELECT 1 FROM "topic_lessons" x WHERE x."topicId" = t.id AND x."position" = 2);

